  "claim_id": "C028",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C028.main",
    "value": "Post-release observation should assess whether documentation of the targeted handoff becomes more consistent.",
    "scope": "A proposed observation of documentary continuity, with no improvement yet reported.",
    "provenance": {
      "refs": [
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P015 specifies assessing handoff documentation after release; P016 identifies this as proposed observation."
    }
  },
  "signal_basis": {
    "component_id": "C028.signal_basis",
    "value": "Record relevant handoff events, inspect histories for continuity and contradictions, and observe whether the targeted handoff is more consistently accounted for after release.",
    "scope": "Assessment of documentary consistency only; observations are proposed, and apparent recording improvement need not reflect changed customer behavior.",
    "provenance": {
      "refs": [
        {
          "source_id": "P003",
          "role": "SUPPORT"
        },
